WITH payload AS (SELECT $1::jsonb AS value), saved_step AS (
  UPDATE analysis_step_outputs SET status = payload.value->>'status', output = payload.value->'output',
    citations = COALESCE(payload.value->'output'->'citations', '[]'::jsonb), diagnostics = COALESCE(payload.value->'output'->'diagnostics', '[]'::jsonb), quality_gate = COALESCE(payload.value->'output'->'quality_gate', '{}'::jsonb), updated_at = NOW()
  FROM payload WHERE run_id = (payload.value->>'run_id')::uuid AND step = payload.value->>'step_key' RETURNING run_id
), saved_run AS (
  UPDATE analysis_runs SET current_step = payload.value->>'step_key', decision_state = payload.value->'decision_state', heartbeat_at = NOW(), lease_expires_at = NOW() + INTERVAL '15 minutes',
    updated_at = NOW()
  FROM payload WHERE id = (payload.value->>'run_id')::uuid RETURNING id
) SELECT value AS result FROM payload;

